// Helper function to get course by code
export const getCourseByCode = (code) => {
  return courseCatalog.find(c => c.courseCode === code);
};

// Helper function to search catalog
export const searchCatalog = (query, admissionYear = null) => {
  if (!query || query.length < 2) return [];
  const searchTerm = query.toLowerCase();
  return courseCatalog.filter(course => 
    course.courseCode.toLowerCase().includes(searchTerm) ||
    course.courseName.toLowerCase().includes(searchTerm)
  ).slice(0, 10);
};

// Helper function to get courses by department
export const getCoursesByDepartment = (department) => {
  return courseCatalog.filter(c => c.department === department);
};

// Helper function to get courses by basket
export const getCoursesByBasket = (basketType) => {
  return courseCatalog.filter(c => c.basketType === basketType);
};

export default courseCatalog;